type Session = { username: string; profile: Profile; name: string }
type ModalRequest = { title: string; content: string; kind?: 'partner' | 'professional' }
type OpenModal = (modal: ModalRequest | null) => void
const clinicPath = '/app/dashboard'
const routeLabels: Record<string, string> = {
  '/app/dashboard': 'Visão geral', '/app/agenda': 'Agenda', '/app/pacientes': 'Pacientes', '/app/profissionais': 'Profissionais', '/app/atendimentos': 'Atendimentos', '/app/evolucoes': 'Evoluções', '/app/financeiro': 'Financeiro', '/app/convenios': 'Convênios', '/app/comunicacao': 'Comunicação', '/app/relatorios': 'Relatórios', '/app/auditoria': 'Auditoria', '/app/usuarios': 'Usuários', '/app/configuracoes': 'Configurações', '/app/minha-agenda': 'Minha agenda', '/app/meus-pacientes': 'Meus pacientes', '/app/meus-atendimentos': 'Atendimentos', '/app/minhas-evolucoes': 'Evoluções', '/app/documentos': 'Documentos', '/admin': 'Visão geral', '/admin/empresas': 'Empresas', '/admin/assinaturas': 'Assinaturas', '/admin/planos': 'Planos', '/admin/tickets': 'Tickets', '/admin/atividade': 'Atividade global',
}
const clinicalNav = [
  { label: 'VISÃO GERAL', items: [['/app/dashboard', 'Visão geral', LayoutDashboard]] },
  { label: 'OPERAÇÃO CLÍNICA', items: [['/app/agenda', 'Agenda', CalendarDays], ['/app/pacientes', 'Pacientes', Users], ['/app/profissionais', 'Profissionais', Stethoscope], ['/app/atendimentos', 'Atendimentos', ClipboardCheck], ['/app/evolucoes', 'Evoluções', FileText]] },
  { label: 'GESTÃO', items: [['/app/financeiro', 'Financeiro', Wallet], ['/app/convenios', 'Convênios', CreditCard], ['/app/comunicacao', 'Comunicação', Mail], ['/app/relatorios', 'Relatórios', Activity], ['/app/auditoria', 'Auditoria', Shield], ['/app/usuarios', 'Usuários', UserCog]] },
  { label: 'SISTEMA', items: [['/app/configuracoes', 'Configurações', Settings]] },
]
const professionalNav = [
  { label: 'ESPAÇO DE TRABALHO', items: [['/app/minha-agenda', 'Minha agenda', CalendarDays], ['/app/meus-pacientes', 'Meus pacientes', Users], ['/app/meus-atendimentos', 'Atendimentos', ClipboardCheck], ['/app/minhas-evolucoes', 'Evoluções', FileText], ['/app/documentos', 'Documentos', FileClock]] },
]
const adminNav = [
  { label: 'BROTHERS CARE', items: [['/admin', 'Visão geral', LayoutDashboard], ['/admin/empresas', 'Empresas', Home], ['/admin/assinaturas', 'Assinaturas', CreditCard], ['/admin/planos', 'Planos', Wallet], ['/admin/tickets', 'Tickets', MessageCircle], ['/admin/atividade', 'Atividade global', Activity]] },
]

export default function App() {
  const [session, setSession] = useState<Session | null>(() => {
    try { return JSON.parse(localStorage.getItem('brothers-care-session') || 'null') as Session | null } catch { return null }
  })
  const [toast, setToast] = useState('')
  const [modal, setModal] = useState<ModalRequest | null>(null)
  const [commandOpen, setCommandOpen] = useState(false)
  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2800) }
  const signIn = (value: Session) => { localStorage.setItem('brothers-care-session', JSON.stringify(value)); setSession(value) }
  const signOut = () => { localStorage.removeItem('brothers-care-session'); setSession(null) }

  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setCommandOpen((open) => !open) }
      if (event.key === 'Escape') { setCommandOpen(false); setModal(null) }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [])

  return <>
    <Routes>
      <Route path="/" element={<Landing />} />
      <Route path="/login" element={session ? <Navigate to={session.profile === 'admin' ? '/admin' : session.profile === 'professional' ? '/app/minha-agenda' : clinicPath} replace /> : <Login onLogin={signIn} />} />
      <Route path="/vitta" element={<VittaPage onAction={() => notify('Nossa equipe entrará em contato em breve.')} />} />
      <Route path="/admin/*" element={session?.profile === 'admin' ? <Workspace session={session} onLogout={signOut} notify={notify} openModal={setModal} /> : <Navigate to="/login" replace />} />
      <Route path="/app/*" element={session && session.profile !== 'admin' ? <Workspace session={session} onLogout={signOut} notify={notify} openModal={setModal} /> : <Navigate to="/login" replace />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
    {commandOpen && <CommandPalette onClose={() => setCommandOpen(false)} />}
    {modal && <Modal title={modal.title} onClose={() => setModal(null)}>{modal.kind === 'partner' ? <PartnerForm onDone={(message) => { setModal(null); notify(message) }} /> : modal.kind === 'professional' ? <ProfessionalForm onDone={(message) => { setModal(null); notify(message) }} /> : <><p className="modal-copy">{modal.content}</p><div className="modal-foot"><button className="button button-outline" onClick={() => setModal(null)}>Fechar</button><button className="button button-primary" onClick={() => { setModal(null); notify('Alterações salvas com sucesso.') }}>Confirmar</button></div></>}</Modal>}
    {toast && <div className="toast"><CheckCircle2 />{toast}</div>}
  </>
}

function Brand({ inverse = false }: { inverse?: boolean }) { return <Link to="/" className="public-brand" style={inverse ? { color: 'white' } : undefined}><span className="brand-mark"><HeartPulse size={18} strokeWidth={2.5} /></span><span>brothers care</span></Link> }

