function Login({ onLogin }: { onLogin: (session: Session) => void }) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const navigate = useNavigate()
  const submit = (event: React.FormEvent) => {
    event.preventDefault()
    const users: Record<string, { password: string; profile: Profile; name: string }> = {
      admin: { password: 'admin', profile: 'admin', name: 'Marina Costa' },
      adminVitta: { password: 'adminVitta', profile: 'clinic', name: 'Mariana Farias' },
      userVitta: { password: 'userVitta', profile: 'professional', name: 'Ana Souza' },
    }
    const user = users[username]
    if (!user || user.password !== password) { setError('Usuário ou senha não conferem. Revise suas credenciais e tente novamente.'); return }
    onLogin({ username, profile: user.profile, name: user.name })
    navigate(user.profile === 'admin' ? '/admin' : user.profile === 'professional' ? '/app/minha-agenda' : clinicPath)
  }
  return <main className="login-page"><section className="login-brand-panel"><Brand inverse /><div className="login-brand-copy"><div className="eyebrow" style={{color:'#63d9be'}}>Cuidado conectado</div><h1>Gestão mais clara.<br/><em>Cuidado mais presente.</em></h1><p>Uma plataforma feita para aproximar profissionais, pacientes e a operação da sua clínica.</p></div><div className="login-brand-foot">© 2026 Brothers Digital · Brothers Care</div></section><section className="login-panel"><div className="login-box"><Brand /><h2>Bem-vindo de volta</h2><p>Acesse seu espaço de trabalho Brothers Care.</p><form className="login-form" onSubmit={submit}><div className="field"><label htmlFor="username">Usuário</label><input id="username" autoComplete="username" placeholder="Seu usuário" value={username} onChange={(event)=>setUsername(event.target.value)} required /></div><div className="field"><label htmlFor="password">Senha</label><input id="password" type="password" autoComplete="current-password" placeholder="Sua senha" value={password} onChange={(event)=>setPassword(event.target.value)} required /></div>{error&&<div className="login-error">{error}</div>}<button className="button button-dark" type="submit">Entrar na plataforma <ArrowRight /></button></form><div className="demo-box"><strong>Acessos para demonstração</strong><div className="demo-row"><span>Super Admin Brothers</span><code>admin / admin</code></div><div className="demo-row"><span>Admin Instituto Vitta</span><code>adminVitta / adminVitta</code></div><div className="demo-row"><span>Profissional Ana Souza</span><code>userVitta / userVitta</code></div></div><p style={{marginTop:18,fontSize:9}}>Ao entrar, você concorda com nossos termos e política de privacidade.</p></div></section></main>
}

function VittaPage({ onAction }: { onAction: () => void }) {
  const services = [[HeartPulse,'Terapia Ocupacional','Autonomia e participação nas atividades do dia a dia.'],[Activity,'Fisioterapia','Movimento, funcionalidade e qualidade de vida.'],[MessageCircle,'Fonoaudiologia','Comunicação, linguagem e deglutição.'],[Sparkles,'Psicologia','Acolhimento e cuidado em cada etapa.'],[Home,'Atendimento domiciliar','Cuidado próximo, no conforto de casa.']] as const
  return <main className="public-page"><header className="public-nav"><Link className="public-brand" to="/vitta"><span className="tenant-logo" style={{width:34,height:34}}>IV</span><span>Instituto Vitta</span></Link><nav className="public-links"><a href="#especialidades">Especialidades</a><a href="#sobre-vitta">A clínica</a><a href="#contato-vitta">Contato</a></nav><button className="button button-primary" onClick={onAction}>Solicitar atendimento <ArrowRight /></button></header><section className="vitta-hero"><div className="eyebrow" style={{color:'#66ddc3'}}>INSTITUTO VITTA REABILITAÇÃO</div><h1>Seu caminho para mais autonomia começa com cuidado.</h1><p>Uma equipe multidisciplinar, atenta à sua história e comprometida com cada conquista, na clínica ou em casa.</p><button className="button button-primary" onClick={onAction}>Solicitar atendimento <ArrowRight /></button></section><section className="public-section" id="sobre-vitta"><div className="section-intro"><div className="eyebrow">Cuidado que acompanha você</div><h2>Um jeito integrado de reabilitar</h2><p>Na Vitta, cada plano é construído junto com você, com escuta, conhecimento e acompanhamento próximo.</p></div><div className="vitta-service-grid" id="especialidades">{services.map(([Icon,title,description])=><article className="feature-card" key={title}><div className="feature-icon"><Icon /></div><h3>{title}</h3><p>{description}</p></article>)}</div></section><section className="public-section" id="contato-vitta"><div className="final-cta"><div><h2>Vamos conversar sobre o seu cuidado?</h2><p>Atendimento em clínica e domiciliar no Rio de Janeiro.</p></div><button className="button button-dark" onClick={onAction}>Solicitar atendimento <ArrowRight /></button></div></section><footer className="public-footer"><Link to="/vitta" className="public-brand"><span className="tenant-logo" style={{width:30,height:30}}>IV</span>Instituto Vitta</Link><span>Rio de Janeiro · Cuidado multidisciplinar</span><Link to="/">Uma plataforma Brothers Digital</Link></footer></main>
}

function Workspace({ session, onLogout, notify, openModal }: { session: Session; onLogout: () => void; notify: (text: string) => void; openModal: OpenModal }) {
  const location = useLocation()
  const navigate = useNavigate()
  const isAdmin = session.profile === 'admin'
  const isProfessional = session.profile === 'professional'
  const [collapsed, setCollapsed] = useState(false)
  const [mobileOpen, setMobileOpen] = useState(false)
  const [activeTab, setActiveTab] = useState('Visão geral')
  const [query, setQuery] = useState('')
  const [loading, setLoading] = useState(false)
  const path = location.pathname
  const navGroups = isAdmin ? adminNav : isProfessional ? professionalNav : clinicalNav
  const allowed = isAdmin ? path.startsWith('/admin') : isProfessional ? ['/app/minha-agenda','/app/meus-pacientes','/app/meus-atendimentos','/app/minhas-evolucoes','/app/documentos'].includes(path) : path.startsWith('/app/')
  useEffect(() => { if (!allowed) navigate(isAdmin ? '/admin' : isProfessional ? '/app/minha-agenda' : clinicPath, { replace: true }) }, [allowed, isAdmin, isProfessional, navigate])
  useEffect(() => {
    setLoading(true)
    const timeout = window.setTimeout(() => setLoading(false), 180)
    return () => window.clearTimeout(timeout)
  }, [path])
  const title = routeLabels[path] || (path.startsWith('/app/pacientes/') ? 'Perfil do paciente' : path.startsWith('/app/profissionais/') ? 'Perfil profissional' : 'Detalhes')
  const menuIcon = (Icon: typeof LayoutDashboard) => <Icon />
  const mobileLinks = isProfessional ? professionalNav[0].items.slice(0,4) : clinicalNav[1].items.slice(0,4)
  return <div className="app-shell">
    <aside className={`sidebar ${collapsed?'collapsed':''} ${mobileOpen?'mobile-open':''}`}><Link to={isAdmin?'/admin':clinicPath} className="brand"><span className="brand-mark"><HeartPulse size={18}/></span>{!collapsed&&<span className="brand-text">brothers care</span>}</Link>{!isAdmin&&<button className="tenant-switch" onClick={()=>notify('Instituto Vitta Reabilitação · Rio de Janeiro') }><span className="tenant-logo">IV</span>{!collapsed&&<><span className="tenant-copy"><strong>{isProfessional?'Instituto Vitta':'Instituto Vitta Reabilitação'}</strong><small>{isProfessional?'Seu espaço profissional':'Plano Professional'}</small></span><ChevronDown size={13}/></>}</button>}{navGroups.map((group)=><div key={group.label}><div className="nav-label">{!collapsed&&group.label}</div><nav className="side-nav">{group.items.map(([href,label,Icon])=><Link key={String(href)} to={href as string} onClick={()=>setMobileOpen(false)} className={`nav-link ${path===href?'active':''}`} title={collapsed?label as string:undefined}>{menuIcon(Icon as typeof LayoutDashboard)}{!collapsed&&<span>{label as string}</span>}{!collapsed&&href==='/app/evolucoes'&&!isProfessional&&<span className="nav-badge">7</span>}</Link>)}</nav></div>)}<div className="side-bottom"><button className="nav-link" onClick={onLogout}><LogOut size={17}/>{!collapsed&&<span>Sair da conta</span>}</button><button className="collapse-btn" onClick={()=>setCollapsed(!collapsed)}><PanelLeftClose size={15}/>{!collapsed&&<span>Recolher menu</span>}</button></div></aside>
    <div className="main-area"><header className="topbar"><div style={{display:'flex',alignItems:'center',gap:10}}><button className="icon-button mobile-menu" onClick={()=>setMobileOpen(!mobileOpen)} aria-label="Abrir menu"><Menu /></button><div className="breadcrumbs"><span>{isAdmin?'Brothers Care':'Instituto Vitta'}</span><ChevronRight size={12}/><strong>{title}</strong></div></div><div className="top-actions"><button className="icon-button" onClick={()=>window.dispatchEvent(new KeyboardEvent('keydown',{key:'k',ctrlKey:true}))} aria-label="Buscar"><Search/></button><button className="icon-button command-trigger" onClick={()=>window.dispatchEvent(new KeyboardEvent('keydown',{key:'k',ctrlKey:true}))} title="Busca rápida"><Command/></button><button className="icon-button" onClick={()=>notify('Você está em dia. Não há novas notificações.')} aria-label="Notificações"><Bell/><i className="notification-dot"/></button><span className="top-divider"/><div className="user-chip"><span className="avatar small">{session.name.split(' ').map((part)=>part[0]).slice(0,2).join('')}</span><div className="user-meta"><strong>{session.name}</strong><small>{isAdmin?'Super Admin':isProfessional?'Terapeuta Ocupacional':'Administradora'}</small></div><button className="icon-button" onClick={()=>notify('Conta e preferências')} aria-label="Abrir perfil"><ChevronDown/></button></div></div></header>
      <main className="content"><PageHeading title={title} path={path} notify={notify} openModal={openModal} />{loading?<PageSkeleton/>:isAdmin?<AdminContent path={path} query={query} setQuery={setQuery} notify={notify} />:<ClinicContent path={path} session={session} activeTab={activeTab} setActiveTab={setActiveTab} query={query} setQuery={setQuery} notify={notify} openModal={openModal} />}</main>
    </div>
    <nav className="mobile-bottom">{mobileLinks.map(([href,label,Icon])=><Link key={String(href)} to={href as string} className={path===href?'active':''}>{menuIcon(Icon as typeof LayoutDashboard)}<span>{label as string}</span></Link>)}</nav>
  </div>
}

function PageHeading({ title, path, notify, openModal }: { title: string; path: string; notify: (text: string) => void; openModal: OpenModal }) {
  const isDashboard = path === clinicPath || path === '/admin'
  const isAgenda = path.includes('agenda')
  const isEvolution = path.includes('evolu')
  const isPatientProfile = path.startsWith('/app/pacientes/')
  const subtitle = isDashboard ? path === '/admin' ? 'Acompanhe a saúde de toda a operação Brothers Care.' : 'Uma visão clara da operação do Instituto Vitta.' : isAgenda ? 'Organize atendimentos, equipe e rotina em um só lugar.' : isEvolution ? 'Registros clínicos organizados para acompanhar cada conquista.' : isPatientProfile ? 'Histórico e informações do cuidado em um só lugar.' : `Gerencie ${title.toLocaleLowerCase('pt-BR')} do Instituto Vitta.`
  let action = <button className="button button-outline" onClick={() => notify('Relatório preparado para exportação.')}><ArrowDownLeft />Exportar</button>
  if (isDashboard || isAgenda) action = <button className="button button-primary" onClick={() => openModal({ title: 'Novo atendimento', content: 'Selecione paciente, profissional, modalidade e horário para adicionar um atendimento à agenda.' })}><Plus />Novo atendimento</button>
  else if (isEvolution) action = <button className="button button-primary" onClick={() => document.getElementById('evolution-patient')?.focus()}><Plus />Nova evolução</button>
  else if (path === '/app/pacientes') action = <button className="button button-primary" onClick={() => openModal({ title: 'Cadastrar paciente', content: 'Preencha os dados do paciente para iniciar o acompanhamento na clínica.' })}><Plus />Novo paciente</button>
  else if (path === '/app/profissionais') action = <button className="button button-primary" onClick={() => openModal({ title: 'Cadastrar profissional', content: 'Preencha os dados profissionais para adicionar à equipe do Instituto Vitta.', kind: 'professional' })}><Plus />Novo profissional</button>
  else if (path === '/admin/empresas') action = <button className="button button-primary" onClick={() => openModal({ title: 'Cadastrar parceiro', content: 'Configure a nova empresa parceira no Brothers Care.', kind: 'partner' })}><Plus />Novo parceiro</button>
  return <div className="page-heading"><div><div className="eyebrow">{path.startsWith('/admin') ? 'PAINEL SAAS · BROTHERS DIGITAL' : path.includes('minha') || path.includes('meu') ? 'ÁREA PROFISSIONAL · INSTITUTO VITTA' : 'INSTITUTO VITTA · RIO DE JANEIRO'}</div><h1>{title}</h1><p>{subtitle}</p></div>{action}</div>
}

function PageSkeleton() { return <div className="skeleton-grid" aria-label="Carregando conteúdo"><div className="skeleton-row"><i/><i/><i/><i/></div><div className="skeleton-main"><i/><i/></div><div className="skeleton-row"><i/><i/></div></div> }

function Kpi({ label, value, note, icon: Icon, tone = 'teal' }: { label: string; value: string; note?: ReactNode; icon: typeof Users; tone?: string }) { return <article className="card kpi-card"><div className="kpi-top"><span>{label}</span><span className="kpi-icon" style={tone==='coral'?{background:'#fff0eb',color:'#c76a56'}:tone==='blue'?{background:'#edf3fb',color:'#6686b1'}:undefined}><Icon/></span></div><div className="kpi-value">{value}</div>{note&&<div className="kpi-note">{note}</div>}</article> }

function ClinicContent({ path, session, activeTab, setActiveTab, query, setQuery, notify, openModal }: { path: string; session: Session; activeTab: string; setActiveTab: (tab: string) => void; query: string; setQuery: (query: string) => void; notify: (text: string) => void; openModal: OpenModal }) {
  if (path===clinicPath) return <ClinicDashboard notify={notify}/>
  if (path==='/app/minha-agenda') return <ProfessionalDashboard notify={notify}/>
  if (path==='/app/agenda'||path==='/app/meus-atendimentos') return <AgendaPage professional={session.profile==='professional'} notify={notify} openModal={openModal}/>
  if (path==='/app/pacientes'||path==='/app/meus-pacientes') return <PatientsPage query={query} setQuery={setQuery} professional={session.profile==='professional'}/>
  if (path.startsWith('/app/pacientes/')) return <PatientDetail activeTab={activeTab} setActiveTab={setActiveTab} />
  if (path==='/app/profissionais') return <ProfessionalsPage query={query} setQuery={setQuery}/>
  if (path.startsWith('/app/profissionais/')) return <ProfessionalDetail />
  if (path==='/app/evolucoes'||path==='/app/minhas-evolucoes') return <EvolutionPage notify={notify} professional={session.profile==='professional'}/>
  if (path==='/app/financeiro') return <FinancePage notify={notify}/>
  if (path==='/app/comunicacao') return <CommunicationPage />
  if (path==='/app/auditoria') return <AuditPage />
  if (path==='/app/relatorios') return <ReportsPage notify={notify}/>
  if (path==='/app/convenios') return <PlansPage />
  if (path==='/app/usuarios') return <UsersPage />
  if (path==='/app/configuracoes') return <SettingsPage notify={notify}/>
  if (path==='/app/documentos') return <DocumentsPage />
  return <ClinicDashboard notify={notify}/>
}

function ClinicDashboard({ notify }: { notify: (text: string) => void }) {
  const pieData = [{name:'Terapia Ocupacional',value:36,color:'#25c6a5'},{name:'Fisioterapia',value:27,color:'#79bfc0'},{name:'Fonoaudiologia',value:18,color:'#f0b35d'},{name:'Psicologia',value:12,color:'#e5806d'},{name:'Outros',value:7,color:'#9c9fb9'}]
  return <><div className="grid kpi-grid"><Kpi label="Pacientes ativos" value="186" note="↑ 8 novos este mês" icon={Users}/><Kpi label="Profissionais" value={String(professionals.length)} note="Equipe multidisciplinar" icon={Stethoscope} tone="blue"/><Kpi label="Atendimentos hoje" value="31" note="6 próximos na agenda" icon={CalendarDays}/><Kpi label="Atendimentos no mês" value="742" note={<><span className="up">↑ 3,6%</span> vs. mês anterior</>} icon={ClipboardCheck}/><Kpi label="Taxa de conclusão" value="94,6%" note="Meta mensal: 92%" icon={CheckCircle2}/><Kpi label="Faturamento previsto" value="R$ 78.450" note="Setembro · fechamento em andamento" icon={CircleDollarSign}/><Kpi label="Evoluções pendentes" value="7" note="2 aguardando revisão" icon={FileText} tone="coral"/><Kpi label="Pendências financeiras" value="12" note="R$ 4.280 em conferência" icon={AlertCircle} tone="coral"/></div><div className="grid dashboard-grid"><div className="card chart-card"><div className="card-heading"><div><h2>Atendimentos realizados</h2><p>Volume mensal da clínica</p></div><div className="chart-legend"><i/>Atendimentos</div></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={monthlyAppointments} margin={{top:8,right:5,left:-22,bottom:0}}><defs><linearGradient id="appointmentsGradient" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#21d5b2" stopOpacity={.24}/><stop offset="90%" stopColor="#21d5b2" stopOpacity={0}/></linearGradient></defs><CartesianGrid stroke="#edf1f2" strokeDasharray="3 4" vertical={false}/><XAxis dataKey="month" axisLine={false} tickLine={false} tick={{fontSize:10,fill:'#93a0a5'}} dy={8}/><YAxis axisLine={false} tickLine={false} tick={{fontSize:9,fill:'#a1adb0'}}/><Tooltip contentStyle={{border:'1px solid #e7eeee',borderRadius:8,fontSize:10,boxShadow:'0 8px 20px #193a3015'}}/><Area type="monotone" dataKey="value" stroke="#25c4a3" strokeWidth={2.5} fill="url(#appointmentsGradient)" activeDot={{r:5,fill:'#25c4a3',stroke:'white',strokeWidth:2}}/></AreaChart></ResponsiveContainer></div></div><div className="side-stack"><div className="card distribution"><div className="card-heading"><div><h2>Atendimentos por especialidade</h2><p>Distribuição no mês</p></div><button className="icon-button" onClick={()=>notify('Distribuição atualizada')}><MoreHorizontal/></button></div><div style={{display:'flex',alignItems:'center',gap:14}}><div style={{width:112,height:112,flex:'none'}}><ResponsiveContainer width="100%" height="100%"><PieChart><Pie data={pieData} dataKey="value" innerRadius={34} outerRadius={51} paddingAngle={3} stroke="none">{pieData.map((entry)=><Cell key={entry.name} fill={entry.color}/>)}</Pie><Tooltip formatter={(value)=>`${value}%`} contentStyle={{fontSize:10,borderRadius:7}}/></PieChart></ResponsiveContainer></div><div className="distribution-list" style={{margin:0,flex:1}}>{pieData.map((item)=><div className="distribution-row" key={item.name}><span className="distribution-label"><i className="dot" style={{background:item.color}}/>{item.name}</span><span className="distribution-value">{item.value}%</span></div>)}</div></div></div><ActivityCard/></div></div><div className="card appointments-card" style={{marginTop:15}}><div className="card-heading"><div><h2>Próximos atendimentos</h2><p>Quarta-feira, 15 de outubro</p></div><Link className="link-button" to="/app/agenda">Ver agenda completa <ArrowRight size={12}/></Link></div><AppointmentList compact/></div></>
}

function ActivityCard() { const activity=[['evolução finalizada','Ana Souza finalizou evolução de Regina Oliveira','Há 12 min'],['novo paciente','Helena Costa foi cadastrada pela recepção','Há 38 min'],['atendimento realizado','Juliana Mendes concluiu sessão de José Almeida','Há 1 h']];return <div className="card activity-card"><div className="card-heading"><div><h2>Atividade recente</h2><p>Atualizações da equipe</p></div></div><div className="activity-list">{activity.map(([title,copy,time],index)=><div className="activity-item" key={title}><span className="activity-icon">{index===0?<FileText/>:index===1?<UserRound/>:<CheckCircle2/>}</span><div className="activity-copy"><strong>{title}</strong><br/>{copy}<small>{time}</small></div></div>)}</div></div> }

function AppointmentList({ compact = false, professional = false, onSelect }: { compact?: boolean; professional?: boolean; onSelect?: (patient: string) => void }) { const items=professional?appointments.filter((item)=>item.professional==='Ana Souza'):appointments;return <div className="appointment-list">{items.slice(0,compact?5:items.length).map((item,index)=><button className="appointment-item" key={`${item.time}-${item.patient}`} style={{width:'100%',textAlign:'left',background:'transparent',border:0}} onClick={()=>onSelect?.(item.patient)}><span className="appointment-time">{item.time}</span><span className="avatar small" style={{background:['#d9eee5','#f6e7d8','#e0e9f5','#eee2f0'][index%4]}}>{item.patient.split(' ').map((part)=>part[0]).slice(0,2).join('')}</span><span className="appointment-copy"><strong>{item.patient}</strong><small>{professional?'Terapia Ocupacional':`${item.professional} · ${item.type}`}</small></span><span className={`status status-${item.status.toLowerCase()}`}>{item.status}</span></button>)}</div> }

function ProfessionalDashboard({ notify }: { notify: (text: string) => void }) { return <><div className="grid kpi-grid" style={{gridTemplateColumns:'repeat(4,minmax(0,1fr))'}}><Kpi label="Atendimentos hoje" value="6" note="Sua agenda de quarta-feira" icon={CalendarDays}/><Kpi label="Concluídos" value="3" note="50% da agenda concluída" icon={CheckCircle2}/><Kpi label="Próximo atendimento" value="14:30" note="Antônio Nogueira · Clínica" icon={Clock3} tone="blue"/><Kpi label="Pendências" value="2" note="Evoluções para finalizar" icon={FileText} tone="coral"/></div><div className="grid dashboard-grid"><div className="card appointments-card"><div className="card-heading"><div><h2>Minha agenda de hoje</h2><p>Quarta-feira, 15 de outubro</p></div><button className="button button-outline" onClick={()=>notify('Visualização semanal aberta.')}><CalendarDays/>Semana</button></div><AppointmentList professional onSelect={(patient)=>notify(`Atendimento de ${patient} selecionado.`)}/></div><div className="side-stack"><div className="card activity-card"><div className="card-heading"><div><h2>Minhas pendências</h2><p>2 evoluções aguardando finalização</p></div></div><div className="activity-list">{evolutions.slice(6,8).map((item)=><div className="activity-item" key={item.id}><span className="activity-icon"><FileText/></span><div className="activity-copy"><strong>{item.patient}</strong><br/>Atendimento de terapia ocupacional<small>Hoje · 10:30</small></div></div>)}</div><Link className="link-button" to="/app/minhas-evolucoes">Ver evoluções <ArrowRight size={12}/></Link></div><div className="card distribution"><div className="card-heading"><div><h2>Seus pacientes</h2><p>Acompanhamento ativo</p></div></div><div className="kpi-value" style={{fontSize:26}}>12</div><div className="kpi-note">4 atendimentos nesta semana</div><Link className="link-button" to="/app/meus-pacientes" style={{display:'inline-block',marginTop:12}}>Ver pacientes <ArrowRight size={12}/></Link></div></div></div></> }

function TableToolbar({ query, setQuery, placeholder, children }: { query: string; setQuery: (value:string)=>void; placeholder:string; children?:React.ReactNode }) { return <div className="table-toolbar"><label className="searchbox"><Search/><input placeholder={placeholder} value={query} onChange={(event)=>setQuery(event.target.value)}/></label><div className="filter-actions">{children}<button className="button button-outline"><Filter/>Filtros</button></div></div> }

function PatientsPage({ query, setQuery, professional }: { query:string; setQuery:(value:string)=>void; professional:boolean }) { const list=(professional?patients.filter((patient)=>patient.professional==='Ana Souza'):patients).filter((patient)=>patient.name.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));return <><div className="grid kpi-grid" style={{gridTemplateColumns:'repeat(3,minmax(0,1fr))'}}><Kpi label="Pacientes ativos" value={professional?'12':'186'} note="Acompanhamento em andamento" icon={Users}/><Kpi label="Novos neste mês" value="8" note="↑ 2 em relação a agosto" icon={UserRound}/><Kpi label="Próximas visitas" value={professional?'6':'42'} note="Nos próximos 7 dias" icon={CalendarDays}/></div><section className="card table-card"><TableToolbar query={query} setQuery={setQuery} placeholder="Buscar paciente por nome..."><select className="select-mini"><option>Todos os status</option><option>Em acompanhamento</option><option>Inativo</option></select></TableToolbar><div className="table-wrap"><table><thead><tr><th>Paciente</th><th>Idade</th><th>Convênio</th><th>Profissional</th><th>Última evolução</th><th>Próxima visita</th><th>Status</th><th></th></tr></thead><tbody>{list.map((patient)=><tr key={patient.id}><td><Link to={`/app/pacientes/${patient.id}`} className="person-cell"><span className="avatar small" style={{background:patient.color}}>{patient.initials}</span><strong>{patient.name}</strong></Link></td><td>{patient.age} anos</td><td>{patient.plan}</td><td>{patient.professional}</td><td>{patient.lastNote}</td><td>{patient.nextVisit}</td><td><span className={`status ${patient.status==='Inativo'?'status-inativo':'status-ativo'}`}>{patient.status}</span></td><td><Link to={`/app/pacientes/${patient.id}`} className="link-button">Abrir</Link></td></tr>)}</tbody></table>{list.length===0&&<div className="empty-state"><Search/><h3>Nenhum paciente encontrado</h3><p>Tente ajustar sua busca.</p></div>}</div><div className="table-footer"><span>Mostrando {list.length} de {professional?'12':'186'} pacientes</span><Pagination/></div></section></> }

function ProfessionalsPage({ query, setQuery }: { query:string; setQuery:(value:string)=>void }) { const list=professionals.filter((person)=>person.name.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR'))||person.specialty.toLocaleLowerCase('pt-BR').includes(query.toLocaleLowerCase('pt-BR')));return <><div className="grid kpi-grid" style={{gridTemplateColumns:'repeat(3,minmax(0,1fr))'}}><Kpi label="Profissionais ativos" value={String(professionals.filter((person)=>person.status==='Ativo').length)} note="Equipe multidisciplinar" icon={Stethoscope}/><Kpi label="Atendimentos no mês" value="742" note="Média de 31 por profissional" icon={ClipboardCheck}/><Kpi label="Agenda ocupada" value="86%" note="Disponibilidade desta semana" icon={CalendarDays}/></div><section className="card table-card"><TableToolbar query={query} setQuery={setQuery} placeholder="Buscar por profissional ou especialidade..."><select className="select-mini"><option>Todas as especialidades</option><option>Fisioterapia</option><option>Terapia Ocupacional</option></select></TableToolbar><div className="table-wrap"><table><thead><tr><th>Profissional</th><th>Especialidade</th><th>Agenda</th><th>Pacientes</th><th>Atendimentos do mês</th><th>Status</th><th></th></tr></thead><tbody>{list.map((person)=><tr key={person.id}><td><Link to={`/app/profissionais/${person.id}`} className="person-cell"><span className="avatar small" style={{background:person.color}}>{person.initials}</span><strong>{person.name}</strong></Link></td><td>{person.specialty}</td><td><span className="status status-bom">Disponível</span></td><td>{person.patients}</td><td>{person.appointments}</td><td><span className={`status ${person.status==='Ativo'?'status-ativo':'status-atenção'}`}>{person.status}</span></td><td><Link to={`/app/profissionais/${person.id}`} className="link-button">Abrir</Link></td></tr>)}</tbody></table></div><div className="table-footer"><span>{professionals.length} profissionais na equipe</span><Pagination/></div></section></> }

function Pagination() { return <div className="pagination"><button aria-label="Página anterior"><ChevronLeft size={13}/></button><button className="active">1</button><button>2</button><button>3</button><button aria-label="Próxima página"><ChevronRight size={13}/></button></div> }

function AgendaPage({ professional, notify, openModal }: { professional:boolean; notify:(text:string)=>void; openModal:(modal:{title:string;content:string}|null)=>void }) { const [view,setView]=useState('Semana');const [filter,setFilter]=useState('Todos os profissionais');return <><div className="card" style={{padding:'14px 17px',marginBottom:14,display:'flex',alignItems:'center',justifyContent:'space-between',gap:10,flexWrap:'wrap'}}><div style={{display:'flex',alignItems:'center',gap:8}}><button className="icon-button" onClick={()=>notify('Período anterior')}><ChevronLeft/></button><strong style={{fontSize:12,color:'#263f4d'}}>13 — 19 de outubro, 2026</strong><button className="icon-button" onClick={()=>notify('Próximo período')}><ChevronRight/></button><button className="button button-outline" onClick={()=>notify('Hoje selecionado')}>Hoje</button></div><div style={{display:'flex',gap:8,flexWrap:'wrap'}}>{!professional&&<select className="select-mini" value={filter} onChange={(event)=>setFilter(event.target.value)}><option>Todos os profissionais</option><option>Ana Souza</option><option>Juliana Mendes</option></select>}<select className="select-mini"><option>Todas as especialidades</option><option>Terapia Ocupacional</option><option>Fisioterapia</option></select><div className="tabs" style={{margin:0,gap:10}}>{['Dia','Semana','Mês','Lista'].map((item)=><button className={`tab ${view===item?'active':''}`} key={item} onClick={()=>setView(item)}>{item}</button>)}</div></div></div>{view==='Lista'?<section className="card appointments-card"><AppointmentList professional={professional} onSelect={(patient)=>openModal({title:`Atendimento · ${patient}`,content:'Paciente, profissional, horário e status do atendimento. Confirme presença, registre evolução ou reagende este horário.'})}/></section>:<div className="card table-card"><div className="table-wrap"><table className="calendar-table"><thead><tr><th>Horário</th>{['Seg 13','Ter 14','Qua 15','Qui 16','Sex 17'].map((day)=><th key={day}>{day}</th>)}</tr></thead><tbody>{['08:00','09:00','10:00','11:00','14:00','15:00','16:00'].map((time,row)=><tr key={time}><td style={{color:'#8c9b9e',fontSize:9}}>{time}</td>{[0,1,2,3,4].map((day)=><td key={`${time}-${day}`} style={{minWidth:135,height:58,whiteSpace:'normal'}}>{((row+day)%3===0||row===4&&day===2)&&<button className="calendar-event" onClick={()=>openModal({title:`Atendimento · ${appointments[(row+day)%appointments.length].patient}`,content:`${time} · ${appointments[(row+day)%appointments.length].professional} · ${appointments[(row+day)%appointments.length].type}. Status: ${appointments[(row+day)%appointments.length].status}.`})}><strong>{appointments[(row+day)%appointments.length].patient}</strong><small>{appointments[(row+day)%appointments.length].professional} · ${time}</small></button>}</td>)}</tr>)}</tbody></table></div></div>}</> }

function PatientDetail({ activeTab, setActiveTab }: { activeTab:string; setActiveTab:(tab:string)=>void }) {
  const patientId = Number(window.location.pathname.split('/').pop()) || 1
  const patient = patients[patientId - 1] || patients[0]
  const tabs = ['Visão geral', 'Evoluções', 'Atendimentos', 'Documentos', 'Financeiro', 'Comunicações']
  return <>
    <div className="card" style={{padding:20,marginBottom:17,display:'flex',alignItems:'center',gap:15,flexWrap:'wrap'}}>
      <span className="avatar" style={{width:52,height:52,fontSize:15,background:patient.color}}>{patient.initials}</span>
      <div style={{flex:1}}><h2 style={{font:'700 17px Manrope',color:'#193649',margin:'0 0 6px'}}>{patient.name}</h2><span style={{fontSize:10,color:'#829297'}}>{patient.age} anos · {patient.plan} · Acompanhamento desde março de 2025</span></div>
      <span className="status status-ativo">{patient.status}</span>
      <button className="button button-outline"><MoreHorizontal/>Ações</button>
    </div>
    <div className="tabs">{tabs.map((tab)=><button className={`tab ${activeTab===tab?'active':''}`} key={tab} onClick={()=>setActiveTab(tab)}>{tab}</button>)}</div>
    {activeTab==='Visão geral'?<div className="two-col"><div className="card card-pad"><h2 className="section-title">Resumo do acompanhamento</h2><p style={{fontSize:11,lineHeight:1.7,color:'#6b7e86',marginTop:12}}>Paciente em acompanhamento de terapia ocupacional, com foco em autonomia nas atividades de vida diária e participação social.</p><div className="grid" style={{gridTemplateColumns:'1fr 1fr',marginTop:16}}><Detail label="Profissional responsável" value={patient.professional}/><Detail label="Próxima visita" value={patient.nextVisit}/><Detail label="Última evolução" value={patient.lastNote}/><Detail label="Plano terapêutico" value="Ativo · revisão em 30 dias"/></div></div><div className="card card-pad"><h2 className="section-title">Próximos atendimentos</h2><AppointmentList compact/></div></div>:activeTab==='Evoluções'?<EvolutionTimeline filterPatient={patient.name}/>:<div className="card empty-state"><FileText/><h3>{activeTab} de {patient.name}</h3><p>As informações serão exibidas nesta seção conforme forem registradas.</p></div>}
  </>
}
function Detail({label,value}:{label:string;value:string}){return <div><div className="eyebrow">{label}</div><div style={{fontSize:11,color:'#304b5a',fontWeight:600}}>{value}</div></div>}
function ProfessionalDetail(){const id=Number(window.location.pathname.split('/').pop())||1;const person=professionals.find((entry)=>entry.id===id)||professionals[0];const startDate=person.startDate?new Date(`${person.startDate}T12:00:00`).toLocaleDateString('pt-BR',{dateStyle:'long'}):'12 de março de 2023';return <><div className="card" style={{padding:20,display:'flex',alignItems:'center',gap:15,marginBottom:16}}><span className="avatar" style={{width:52,height:52,background:person.color}}>{person.initials}</span><div style={{flex:1}}><h2 style={{font:'700 17px Manrope',margin:'0 0 5px',color:'#193649'}}>{person.name}</h2><span style={{fontSize:10,color:'#829297'}}>{person.specialty} · Instituto Vitta</span></div><span className="status status-ativo">{person.status}</span><button className="button button-outline"><MoreHorizontal/>Ações</button></div><div className="grid kpi-grid" style={{gridTemplateColumns:'repeat(3,minmax(0,1fr))'}}><Kpi label="Pacientes ativos" value={String(person.patients)} note="Acompanhamento atual" icon={Users}/><Kpi label="Atendimentos no mês" value={String(person.appointments)} note="Setembro de 2026" icon={ClipboardCheck}/><Kpi label="Agenda ocupada" value="88%" note="Disponibilidade semanal" icon={CalendarDays}/></div><div className="grid two-col"><div className="card appointments-card"><div className="card-heading"><div><h2>Próximos atendimentos</h2><p>Agenda desta semana</p></div></div><AppointmentList professional/></div><div className="card card-pad"><h2 className="section-title">Dados profissionais</h2><div className="grid" style={{gap:18,marginTop:17}}><Detail label="Especialidade" value={person.specialty}/><Detail label="Conselho profissional" value={person.license||'CREFITO-2 · 18452-TO'}/><Detail label="E-mail" value={person.email||`${person.name.toLowerCase().replace(' ','.')}@institutovitta.com.br`}/><Detail label="Telefone" value={person.phone||'Não informado'}/><Detail label="Disponibilidade semanal" value={person.workload||'Horários flexíveis'}/><Detail label="Início na clínica" value={startDate}/></div></div></div></>}
